<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from "vue";
import { Banknote, FileDown, FilePlus2, LoaderCircle, Pause, Pencil, Play, Plus, ReceiptText, RotateCcw, Trash2, Undo2, X } from "lucide-vue-next";
import ConfirmModal from "@/components/operations/ConfirmModal.vue";
import DataPanel from "@/components/operations/DataPanel.vue";
import OpsModal from "@/components/operations/OpsModal.vue";
import StatusBadge from "@/components/operations/StatusBadge.vue";
import AdminPromotionsReferrals from "@/views/admin/AdminPromotionsReferrals.vue";
import { operationsRepository } from "@/data/repositories/operationsRepository";
import type { UiCatalogRecord, UiInstitutePriceRecord, UiInstituteRecord, UiInvoiceRecord, UiPaymentRecord, UiSubscriptionRecord } from "@/data/models/operations";
import { currentUser } from "@/lib/api";

type Tab = "plans" | "discounts" | "institute-prices" | "promotions" | "subscriptions" | "invoices" | "payments";
const tabs: Array<{ key: Tab; label: string }> = [{ key: "plans", label: "Plans" }, { key: "discounts", label: "Discounts" }, { key: "institute-prices", label: "Institute prices" }, { key: "promotions", label: "Promotions & referrals" }, { key: "subscriptions", label: "Subscriptions" }, { key: "invoices", label: "Invoices" }, { key: "payments", label: "Payments & refunds" }];
const tab = ref<Tab>("plans"); const loading = ref(false); const saving = ref(false); const deleting = ref(false); const showForm = ref(false); const error = ref("");
const catalogRows = ref<UiCatalogRecord[]>([]); const subscriptions = ref<UiSubscriptionRecord[]>([]); const invoices = ref<UiInvoiceRecord[]>([]); const payments = ref<UiPaymentRecord[]>([]);
const prices = ref<UiInstitutePriceRecord[]>([]); const institutes = ref<UiInstituteRecord[]>([]); const plans = ref<UiCatalogRecord[]>([]); const paymentInvoice = ref<UiInvoiceRecord | null>(null);
const courses = ref<UiCatalogRecord[]>([]); const subjects = ref<UiCatalogRecord[]>([]);
const editingId = ref<number | null>(null); const deleteTarget = ref<UiCatalogRecord | UiInstitutePriceRecord | null>(null);
const form = reactive({ name: "", code: "", scope: "subject", course_id: 0, subject_ids: [] as number[], price: "9.99", currency: "GBP", billing_interval: "month", discount_type: "percentage", percentage: 10, amount: "0", institute_id: 0, plan_id: 0 });
const payment = reactive({ provider: "manual", provider_payment_id: "", amount: "0", currency: "GBP" });
const refundPayment = ref<UiPaymentRecord | null>(null); const refund = reactive({ amount: "0", reason: "", revoke_entitlement: false });
const title = computed(() => tabs.find((item) => item.key === tab.value)?.label || "Finance");
const canRecordPayment = computed(() => currentUser()?.roles?.some((role) => role.slug === "system_admin") ?? false);
const money = (minor: number, currency = "GBP") => new Intl.NumberFormat(undefined, { style: "currency", currency }).format(minor / 100);
const instituteName = (id: number) => institutes.value.find((item) => item.id === id)?.name || `Institute #${id}`;
const planName = (id: number) => plans.value.find((item) => item.id === id)?.name || `Plan #${id}`;
const planTarget = (item: UiCatalogRecord) => item.scope === "course" ? item.courseName || "No course selected" : ["subject", "multi_subject"].includes(item.scope) ? item.subjectNames.join(", ") || "No subjects selected" : item.scope.replaceAll("_", " ");
const planSelectionValid = computed(() => tab.value !== "plans" || (form.scope === "course" ? form.course_id > 0 : form.scope === "subject" ? form.subject_ids.length === 1 : form.scope === "multi_subject" ? form.subject_ids.length >= 2 : true));

async function load() { loading.value = true; error.value = ""; try { if (tab.value === "plans") { const [planPage, coursePage, subjectPage] = await Promise.all([operationsRepository.plans({ per_page: 100 }), operationsRepository.courses({ per_page: 100 }), operationsRepository.subjects({ per_page: 100 })]); catalogRows.value = planPage.items; courses.value = coursePage.items; subjects.value = subjectPage.items; } else if (tab.value === "discounts") catalogRows.value = (await operationsRepository.discounts({ per_page: 100 })).items; else if (tab.value === "institute-prices") { const [pricePage, institutePage, planPage] = await Promise.all([operationsRepository.institutePrices({ per_page: 100 }), operationsRepository.institutes({ per_page: 100 }), operationsRepository.plans({ per_page: 100 })]); prices.value = pricePage.items; institutes.value = institutePage.items; plans.value = planPage.items; } else if (tab.value === "promotions") { /* child view loads its own reporting data */ } else if (tab.value === "subscriptions") subscriptions.value = (await operationsRepository.subscriptions({ per_page: 100 })).items; else if (tab.value === "invoices") invoices.value = (await operationsRepository.invoices({ per_page: 100 })).items; else payments.value = (await operationsRepository.payments({ per_page: 100 })).items; } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to load finance data."; } finally { loading.value = false; } }
function resetForm() { Object.assign(form, { name: "", code: "", scope: "subject", course_id: 0, subject_ids: [], price: "9.99", currency: "GBP", billing_interval: "month", discount_type: "percentage", percentage: 10, amount: "0", institute_id: 0, plan_id: 0 }); }
function openCreate() { editingId.value = null; resetForm(); showForm.value = true; }
function openEdit(item: UiCatalogRecord | UiInstitutePriceRecord) { editingId.value = item.id; if (tab.value === "institute-prices") { const price = item as UiInstitutePriceRecord; Object.assign(form, { institute_id: price.instituteId, plan_id: price.planId, price: String(price.priceMinor / 100), currency: price.currency }); } else { const record = item as UiCatalogRecord; Object.assign(form, { name: record.name, code: record.code, scope: record.scope || record.detail || "subject", course_id: record.courseId || 0, subject_ids: [...record.subjectIds], price: String(record.priceMinor / 100), currency: record.currency, billing_interval: record.billingInterval, discount_type: record.discountType || "percentage", percentage: record.percentage, amount: String(record.amountMinor / 100) }); } showForm.value = true; }
function recordPayload() { return tab.value === "plans" ? { name: form.name, code: form.code, scope: form.scope, course_id: form.scope === "course" ? form.course_id : null, subject_ids: ["subject", "multi_subject"].includes(form.scope) ? form.subject_ids : [], billing_interval: form.billing_interval, billing_interval_count: 1, price_minor: Math.round(Number(form.price) * 100), currency: form.currency, is_public: true, is_active: true, features: [], metadata: {} } : tab.value === "institute-prices" ? { institute_id: form.institute_id, plan_id: form.plan_id, price_minor: Math.round(Number(form.price) * 100), currency: form.currency, starts_at: null, ends_at: null, is_active: true, metadata: {} } : { name: form.name, code: form.code || null, discount_type: form.discount_type, amount_minor: form.discount_type === "fixed" ? Math.round(Number(form.amount) * 100) : null, percentage: form.discount_type === "percentage" ? form.percentage : null, institute_id: null, plan_id: null, starts_at: null, ends_at: null, max_redemptions: null, is_active: true, rules: {} }; }
function changePlanScope() { form.course_id = 0; form.subject_ids = []; }
function togglePlanSubject(id: number) { if (form.scope === "subject") form.subject_ids = [id]; else form.subject_ids = form.subject_ids.includes(id) ? form.subject_ids.filter((item) => item !== id) : [...form.subject_ids, id]; }
function financeResource() { return tab.value === "institute-prices" ? "institute-plan-prices" : tab.value; }
async function saveRecord() { saving.value = true; error.value = ""; try { const resource = financeResource(); if (editingId.value) await operationsRepository.update(resource, editingId.value, recordPayload()); else await operationsRepository.create(resource, recordPayload()); showForm.value = false; await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to save record."; } finally { saving.value = false; } }
async function confirmRemove() { if (!deleteTarget.value) return; deleting.value = true; try { await operationsRepository.remove(financeResource(), deleteTarget.value.id); deleteTarget.value = null; await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to delete record."; } finally { deleting.value = false; } }
async function state(item: UiSubscriptionRecord, action: "cancel" | "resume" | "pause" | "activate") { try { await operationsRepository.changeSubscription(item.id, action); await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to change subscription."; } }
async function createInvoice(item: UiSubscriptionRecord) { try { await operationsRepository.create("invoices", { subscription_id: item.id, tax_minor: 0, discount_minor: 0 }); tab.value = "invoices"; } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to create invoice."; } }
function openPayment(item: UiInvoiceRecord) { paymentInvoice.value = item; payment.amount = String(Math.max(0, item.totalMinor - item.paidMinor) / 100); payment.currency = item.currency; }
function canRefundPayment(item: UiPaymentRecord) { return canRecordPayment.value && ["jazzcash", "google_pay"].includes(item.provider) && ["succeeded", "partially_refunded"].includes(item.status) && item.refundedMinor < item.amountMinor; }
async function recordPayment() { if (!paymentInvoice.value) return; saving.value = true; try { await operationsRepository.recordPayment(paymentInvoice.value.id, { provider: payment.provider, provider_payment_id: payment.provider_payment_id || null, amount_minor: Math.round(Number(payment.amount) * 100), currency: payment.currency }); paymentInvoice.value = null; await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to record payment."; } finally { saving.value = false; } }
function openRefund(item: UiPaymentRecord) { refundPayment.value = item; refund.amount = String(Math.max(0, item.amountMinor - item.refundedMinor) / 100); refund.reason = ""; refund.revoke_entitlement = item.refundedMinor === 0; }
async function issueRefund() { if (!refundPayment.value) return; saving.value = true; error.value = ""; try { await operationsRepository.refundPayment(refundPayment.value.id, { amount_minor: Math.round(Number(refund.amount) * 100), reason: refund.reason, revoke_entitlement: refund.revoke_entitlement }); refundPayment.value = null; await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to issue refund."; } finally { saving.value = false; } }
watch(tab, () => { showForm.value = false; editingId.value = null; deleteTarget.value = null; load(); }); onMounted(load);
</script>

<template><div class="space-y-5"><div class="flex flex-wrap items-end justify-between gap-3"><div><p class="text-[12px] font-semibold uppercase tracking-[0.12em] text-gold">Commercial operations</p><h2 class="mt-1 text-[26px] font-bold tracking-[-0.035em]">Billing and plans</h2><p class="mt-1 text-[13px] text-ink3">Plans, discounts, subscriptions and invoice lifecycle.</p></div><button v-if="tab === 'plans' || tab === 'discounts' || tab === 'institute-prices'" class="ops-button-primary flex items-center gap-2 transition hover:-translate-y-0.5 hover:shadow-md" @click="openCreate"><Plus :size="15" /> New {{ tab === 'plans' ? 'plan' : tab === 'discounts' ? 'discount' : 'price' }}</button></div><p v-if="error" class="rounded-xl bg-pink-light px-4 py-3 text-[13px] text-pink">{{ error }}</p><div class="flex flex-wrap gap-1 rounded-xl border border-border bg-bg-card p-1.5"><button v-for="item in tabs" :key="item.key" class="rounded-lg px-4 py-2 text-[12px] font-semibold transition" :class="tab === item.key ? 'bg-blue text-white shadow-sm' : 'text-ink3 hover:bg-bg-soft'" @click="tab = item.key">{{ item.label }}</button></div>
  <DataPanel v-if="tab === 'plans' || tab === 'discounts'" :title="title" :description="`${catalogRows.length} records`" :loading="loading" :empty="!catalogRows.length"><div class="grid gap-4 p-5 md:grid-cols-2 xl:grid-cols-3"><article v-for="item in catalogRows" :key="item.id" class="group rounded-2xl border border-border p-4 transition hover:-translate-y-0.5 hover:shadow-md"><div class="flex justify-between"><StatusBadge :value="item.status" /><span class="font-mono text-[11px] text-ink3">{{ item.code }}</span></div><h3 class="mt-4 text-[15px] font-bold">{{ item.name }}</h3><p class="mt-1 text-[12px] capitalize text-ink3">{{ item.detail.replaceAll('_', ' ') }}</p><p v-if="tab === 'plans'" class="mt-2 rounded-lg bg-bg-soft px-2.5 py-2 text-[11px] font-semibold text-ink2">{{ planTarget(item) }}</p><p v-if="item.priceMinor" class="mt-4 text-[22px] font-bold text-ink">{{ money(item.priceMinor, item.currency) }}</p><div class="mt-4 flex justify-end gap-1 border-t border-border pt-3"><button class="ops-icon-button" title="Edit" @click="openEdit(item)"><Pencil :size="14" /></button><button class="ops-icon-button hover:bg-pink-light hover:text-pink" title="Delete" @click="deleteTarget = item"><Trash2 :size="14" /></button></div></article></div></DataPanel>
  <DataPanel v-else-if="tab === 'institute-prices'" title="Institute prices" :description="`${prices.length} overrides`" :loading="loading" :empty="!prices.length"><div class="overflow-x-auto"><table class="w-full min-w-[760px] text-left text-[12px]"><thead class="bg-bg-soft text-ink3"><tr><th class="px-5 py-3">Institute</th><th class="px-4 py-3">Plan</th><th class="px-4 py-3">Price</th><th class="px-4 py-3">Period</th><th class="px-4 py-3">Status</th><th class="px-5 py-3 text-right">Actions</th></tr></thead><tbody class="divide-y divide-border"><tr v-for="item in prices" :key="item.id" class="transition hover:bg-bg-soft/70"><td class="px-5 py-3.5 font-semibold">{{ instituteName(item.instituteId) }}</td><td class="px-4 py-3.5">{{ planName(item.planId) }}</td><td class="px-4 py-3.5 font-semibold">{{ money(item.priceMinor, item.currency) }}</td><td class="px-4 py-3.5 text-ink3">{{ item.startsAt ? new Date(item.startsAt).toLocaleDateString() : 'Immediately' }} – {{ item.endsAt ? new Date(item.endsAt).toLocaleDateString() : 'Open ended' }}</td><td class="px-4 py-3.5"><StatusBadge :value="item.active ? 'active' : 'inactive'" /></td><td class="px-5 py-3.5"><div class="flex justify-end gap-1"><button class="ops-icon-button" title="Edit" @click="openEdit(item)"><Pencil :size="14" /></button><button class="ops-icon-button hover:bg-pink-light hover:text-pink" title="Delete" @click="deleteTarget = item"><Trash2 :size="14" /></button></div></td></tr></tbody></table></div></DataPanel>
  <AdminPromotionsReferrals v-else-if="tab === 'promotions'" />
  <DataPanel v-else-if="tab === 'subscriptions'" title="Subscriptions" :description="`${subscriptions.length} records`" :loading="loading" :empty="!subscriptions.length"><div class="overflow-x-auto"><table class="w-full min-w-[820px] text-left text-[12px]"><thead class="bg-bg-soft text-ink3"><tr><th class="px-5 py-3">Plan</th><th class="px-4 py-3">Subscriber</th><th class="px-4 py-3">Period end</th><th class="px-4 py-3">Status</th><th class="px-5 py-3 text-right">Actions</th></tr></thead><tbody class="divide-y divide-border"><tr v-for="item in subscriptions" :key="item.id"><td class="px-5 py-3.5 font-semibold">{{ item.planName }}</td><td class="px-4 py-3.5 text-ink2">User #{{ item.subscriberId }}</td><td class="px-4 py-3.5 text-ink3">{{ item.periodEnd ? new Date(item.periodEnd).toLocaleDateString() : '—' }}</td><td class="px-4 py-3.5"><StatusBadge :value="item.status" /></td><td class="px-5 py-3.5"><div class="flex justify-end gap-1"><button title="Create invoice" class="ops-icon-button" @click="createInvoice(item)"><FilePlus2 :size="14" /></button><button v-if="item.status === 'active'" title="Pause" class="ops-icon-button" @click="state(item, 'pause')"><Pause :size="14" /></button><button v-if="item.status === 'paused'" title="Activate" class="ops-icon-button" @click="state(item, 'activate')"><Play :size="14" /></button><button v-if="item.cancelAtPeriodEnd" title="Resume" class="ops-icon-button" @click="state(item, 'resume')"><RotateCcw :size="14" /></button></div></td></tr></tbody></table></div></DataPanel>
  <DataPanel v-else-if="tab === 'invoices'" title="Invoices" :description="`${invoices.length} records`" :loading="loading" :empty="!invoices.length"><div class="overflow-x-auto"><table class="w-full min-w-[820px] text-left text-[12px]"><thead class="bg-bg-soft text-ink3"><tr><th class="px-5 py-3">Invoice</th><th class="px-4 py-3">Due</th><th class="px-4 py-3">Paid</th><th class="px-4 py-3">Total</th><th class="px-4 py-3">Status</th><th class="px-5 py-3 text-right">Actions</th></tr></thead><tbody class="divide-y divide-border"><tr v-for="item in invoices" :key="item.id"><td class="px-5 py-3.5 font-mono font-semibold">{{ item.number }}</td><td class="px-4 py-3.5 text-ink3">{{ item.dueAt ? new Date(item.dueAt).toLocaleDateString() : '—' }}<p v-if="item.retryCount" class="text-[10px] text-pink">Retry {{ item.retryCount }}</p></td><td class="px-4 py-3.5">{{ money(item.paidMinor, item.currency) }}</td><td class="px-4 py-3.5 font-semibold">{{ money(item.totalMinor, item.currency) }}</td><td class="px-4 py-3.5"><StatusBadge :value="item.status" /></td><td class="px-5 py-3.5"><div class="flex justify-end gap-1"><button class="ops-icon-button" title="Download invoice" @click="operationsRepository.downloadInvoice(item.id, item.number)"><FileDown :size="13" /></button><button v-if="canRecordPayment && item.paidMinor < item.totalMinor" class="inline-flex items-center gap-1.5 rounded-lg border border-border px-2.5 py-1.5 text-[11px] font-semibold hover:bg-mint-light hover:text-mint" @click="openPayment(item)"><Banknote :size="13" /> Record payment</button></div></td></tr></tbody></table></div></DataPanel>
  <DataPanel v-else title="Payments and refunds" :description="`${payments.length} attempts`" :loading="loading" :empty="!payments.length"><div class="overflow-x-auto"><table class="w-full min-w-[920px] text-left text-[12px]"><thead class="bg-bg-soft text-ink3"><tr><th class="px-5 py-3">Invoice</th><th class="px-4 py-3">Provider</th><th class="px-4 py-3">Amount</th><th class="px-4 py-3">Refunded</th><th class="px-4 py-3">Status</th><th class="px-5 py-3 text-right">Actions</th></tr></thead><tbody class="divide-y divide-border"><tr v-for="item in payments" :key="item.id"><td class="px-5 py-3.5 font-mono">{{ item.invoiceNumber || `#${item.invoiceId}` }}</td><td class="px-4 py-3.5 capitalize">{{ item.provider.replaceAll('_', ' ') }}<p class="text-[10px] text-ink3">Attempt {{ item.attemptNumber }}</p></td><td class="px-4 py-3.5 font-semibold">{{ money(item.amountMinor, item.currency) }}</td><td class="px-4 py-3.5">{{ money(item.refundedMinor, item.currency) }}</td><td class="px-4 py-3.5"><StatusBadge :value="item.status" /></td><td class="px-5 py-3.5"><div class="flex justify-end gap-1"><button v-if="item.receiptNumber" class="ops-icon-button" title="Download receipt" @click="operationsRepository.downloadReceipt(item.id, item.receiptNumber)"><ReceiptText :size="14" /></button><button v-if="canRefundPayment(item)" class="ops-icon-button text-pink" title="Issue refund" @click="openRefund(item)"><Undo2 :size="14" /></button></div></td></tr></tbody></table></div></DataPanel>
  <OpsModal :open="showForm" max-width="max-w-lg" :close-on-backdrop="!saving" @close="showForm = false">
    <form class="max-h-[88vh] overflow-y-auto rounded-2xl border border-border bg-bg-card p-5 shadow-2xl" @submit.prevent="saveRecord">
      <div class="mb-5 flex justify-between"><div><h3 class="text-[17px] font-bold">{{ editingId ? 'Edit' : 'New' }} {{ tab === 'plans' ? 'plan' : tab === 'discounts' ? 'discount' : 'institute price' }}</h3><p class="mt-1 text-[12px] text-ink3">Configure the commercial record.</p></div><button type="button" :disabled="saving" @click="showForm = false"><X :size="18" /></button></div>
      <div class="space-y-3">
        <template v-if="tab !== 'institute-prices'"><label class="text-[11px] font-semibold">Name<input v-model="form.name" required class="ops-input" /></label><label class="text-[11px] font-semibold">Code<input v-model="form.code" class="ops-input uppercase" /></label></template>
        <template v-if="tab === 'plans'">
          <label class="text-[11px] font-semibold">Plan applies to<select v-model="form.scope" class="ops-input" @change="changePlanScope"><option value="subject">One subject</option><option value="multi_subject">Multiple subjects</option><option value="course">Course</option><option value="all_subjects">All subjects</option><option value="institute">Institute</option></select></label>
          <label v-if="form.scope === 'course'" class="text-[11px] font-semibold">Course<select v-model.number="form.course_id" required class="ops-input"><option :value="0" disabled>Select a course</option><option v-for="item in courses" :key="item.id" :value="item.id">{{ item.name }}</option></select></label>
          <div v-else-if="form.scope === 'subject' || form.scope === 'multi_subject'" class="space-y-2">
            <div class="flex items-center justify-between"><span class="text-[11px] font-semibold">{{ form.scope === 'subject' ? 'Select one subject' : 'Select two or more subjects' }}</span><span class="text-[10px] text-ink3">{{ form.subject_ids.length }} selected</span></div>
            <div class="max-h-48 space-y-1 overflow-y-auto rounded-xl border border-border bg-bg-soft p-2">
              <button v-for="item in subjects" :key="item.id" type="button" class="flex w-full items-center gap-2 rounded-lg px-3 py-2 text-left text-[12px] transition" :class="form.subject_ids.includes(item.id) ? 'bg-blue text-white shadow-sm' : 'bg-bg-card text-ink2 hover:bg-blue/10'" @click="togglePlanSubject(item.id)"><span class="grid h-4 w-4 place-items-center rounded border" :class="form.subject_ids.includes(item.id) ? 'border-white bg-white/20' : 'border-border'">{{ form.subject_ids.includes(item.id) ? '✓' : '' }}</span><span class="font-semibold">{{ item.name }}</span></button>
              <p v-if="!subjects.length" class="px-3 py-4 text-center text-[11px] text-ink3">Create active subjects before configuring this plan.</p>
            </div>
            <p v-if="!planSelectionValid" class="text-[11px] font-semibold text-pink">{{ form.scope === 'subject' ? 'Choose exactly one subject.' : 'Choose at least two subjects.' }}</p>
          </div>
          <div class="grid grid-cols-2 gap-3"><label class="text-[11px] font-semibold">Price<input v-model="form.price" required type="number" min="0" step="0.01" class="ops-input" /></label><label class="text-[11px] font-semibold">Currency<input v-model="form.currency" required maxlength="3" class="ops-input uppercase" /></label></div>
          <label class="text-[11px] font-semibold">Billing interval<select v-model="form.billing_interval" class="ops-input"><option value="month">Monthly</option><option value="year">Yearly</option></select></label>
        </template>
        <template v-else-if="tab === 'discounts'"><label class="text-[11px] font-semibold">Type<select v-model="form.discount_type" class="ops-input"><option value="percentage">Percentage</option><option value="fixed">Fixed amount</option></select></label><label v-if="form.discount_type === 'percentage'" class="text-[11px] font-semibold">Percentage<input v-model.number="form.percentage" type="number" min="0" max="100" class="ops-input" /></label><label v-else class="text-[11px] font-semibold">Amount<input v-model="form.amount" type="number" min="0" step="0.01" class="ops-input" /></label></template>
        <template v-else><label class="text-[11px] font-semibold">Institute<select v-model.number="form.institute_id" required class="ops-input"><option :value="0" disabled>Select institute</option><option v-for="item in institutes" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label class="text-[11px] font-semibold">Plan<select v-model.number="form.plan_id" required class="ops-input"><option :value="0" disabled>Select plan</option><option v-for="item in plans" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><div class="grid grid-cols-2 gap-3"><label class="text-[11px] font-semibold">Price<input v-model="form.price" required type="number" min="0" step="0.01" class="ops-input" /></label><label class="text-[11px] font-semibold">Currency<input v-model="form.currency" required maxlength="3" class="ops-input uppercase" /></label></div></template>
      </div>
      <div class="mt-5 flex justify-end gap-2"><button type="button" :disabled="saving" class="ops-button-secondary" @click="showForm = false">Cancel</button><button :disabled="saving || !planSelectionValid" class="ops-button-primary inline-flex min-w-28 items-center justify-center gap-2 disabled:cursor-not-allowed disabled:opacity-50"><LoaderCircle v-if="saving" :size="14" class="animate-spin" />{{ saving ? 'Saving…' : editingId ? 'Update' : 'Create' }}</button></div>
    </form>
  </OpsModal>
  <OpsModal :open="Boolean(paymentInvoice)" max-width="max-w-md" :close-on-backdrop="!saving" @close="paymentInvoice = null"><form class="rounded-2xl border border-border bg-bg-card p-5 shadow-2xl" @submit.prevent="recordPayment"><div class="mb-5 flex justify-between"><div><h3 class="text-[17px] font-bold">Record invoice payment</h3><p class="mt-1 text-[12px] text-ink3">{{ paymentInvoice?.number }}</p></div><button type="button" :disabled="saving" @click="paymentInvoice = null"><X :size="18" /></button></div><div class="space-y-3"><label class="text-[11px] font-semibold">Provider<input v-model="payment.provider" required class="ops-input" /></label><label class="text-[11px] font-semibold">Provider reference<input v-model="payment.provider_payment_id" class="ops-input" /></label><div class="grid grid-cols-2 gap-3"><label class="text-[11px] font-semibold">Amount<input v-model="payment.amount" required type="number" min="0.01" step="0.01" class="ops-input" /></label><label class="text-[11px] font-semibold">Currency<input v-model="payment.currency" required maxlength="3" class="ops-input uppercase" /></label></div></div><div class="mt-5 flex justify-end gap-2"><button type="button" :disabled="saving" class="ops-button-secondary" @click="paymentInvoice = null">Cancel</button><button :disabled="saving" class="ops-button-primary inline-flex min-w-36 items-center justify-center gap-2"><LoaderCircle v-if="saving" :size="14" class="animate-spin" />{{ saving ? 'Saving…' : 'Record payment' }}</button></div></form></OpsModal>
  <OpsModal :open="Boolean(refundPayment)" max-width="max-w-md" :close-on-backdrop="!saving" @close="refundPayment = null"><form class="rounded-2xl border border-border bg-bg-card p-5 shadow-2xl" @submit.prevent="issueRefund"><div class="mb-5 flex justify-between"><div><h3 class="text-[17px] font-bold">Issue provider refund</h3><p class="mt-1 text-[12px] text-ink3">{{ refundPayment?.invoiceNumber }} · refundable {{ money((refundPayment?.amountMinor || 0) - (refundPayment?.refundedMinor || 0), refundPayment?.currency) }}</p></div><button type="button" :disabled="saving" @click="refundPayment = null"><X :size="18" /></button></div><div class="space-y-3"><label class="text-[11px] font-semibold">Refund amount<input v-model="refund.amount" required type="number" min="0.01" :max="((refundPayment?.amountMinor || 0) - (refundPayment?.refundedMinor || 0)) / 100" step="0.01" class="ops-input" /></label><label class="text-[11px] font-semibold">Reason<textarea v-model="refund.reason" required maxlength="500" class="ops-input min-h-24" /></label><label class="flex items-start gap-2 rounded-xl bg-bg-soft p-3 text-[11px] font-semibold"><input v-model="refund.revoke_entitlement" type="checkbox" class="mt-0.5" /><span>Revoke or downgrade the student's subscription entitlement after this refund.</span></label></div><div class="mt-5 flex justify-end gap-2"><button type="button" :disabled="saving" class="ops-button-secondary" @click="refundPayment = null">Cancel</button><button :disabled="saving" class="ops-button-primary inline-flex min-w-32 items-center justify-center gap-2"><LoaderCircle v-if="saving" :size="14" class="animate-spin" />{{ saving ? 'Refunding…' : 'Issue refund' }}</button></div></form></OpsModal>
  <ConfirmModal :open="Boolean(deleteTarget)" title="Delete finance record?" message="This record will be removed permanently. Related billing records may prevent deletion." confirm-label="Delete record" :busy="deleting" @close="deleteTarget = null" @confirm="confirmRemove" />
</div></template>
